item.command:
/bin/bash -lc 'research_dir=$(mktemp -d "$TMPDIR/govt_vrinda_search2.XXXXXX")
queries=(
 '"'\"Vrinda Sahay\" \"Dabra\" college'
 '\"शासकीय वृंदा सहाय\" डबरा महाविद्यालय'
 '\"Vrinda Sahay PG College\"'
 '\"Govt Vrinda Sahay PG College Dabra\" website'
)
idx=0
for q in \""'${queries[@]}"; do idx=$((idx+1)); enc=$(printf '"'%s' \""'$q" | jq -sRr @uri); 
  for engine in brave ddg google startpage; do
    case "$engine" in
      brave) url="https://search.brave.com/search?q=$enc";;
      ddg) url="https://lite.duckduckgo.com/lite/?q=$enc";;
      google) url="https://www.google.co.in/search?gbv=1&num=10&q=$enc";;
      startpage) url="https://www.startpage.com/sp/search?query=$enc";;
    esac
    file="$research_dir/q${idx}_${engine}.html";
    if ! curl -L --fail --max-time 20 -sS "$url" -o "$file"; then curl --insecure -L --fail --max-time 20 -sS "$url" -o "$file" || true; fi
  done
done
printf '"'%s\\n' \""'$research_dir"
for f in "$research_dir"/*.html; do echo "---$(basename "$f")"; rg -o -i '"'https?://["'^"<> ]+'"' \""'$f" | sed '"'s/&amp;/\\&/g' | rg -v 'google|bing|brave|duckduckgo|startpage|youtube|facebook|instagram|linkedin|wikipedia' | sed -n '1,20p'; rg -n -i -C 1 'Vrinda|Sahay|Dabra|college|महाविद्यालय|डबरा|वृंदा' \""'$f" | sed -E '"'s/<["'^>]+>/ /g; s/&quot;/"/g; s/&amp;/'"\\&/g; s/[[:space:]]+/ /g' | sed -n '1,30p'; done"

